  "109": {
    "question": "A community health nurse is working with clients to make long-standing, health-related changes using the transtheoretical model. Place the stages of the transtheoretical model in order from first to last.",
    "options": [
      {
        "label": "A",
        "text": "Contemplation → Precontemplation → Preparation → Action → Maintenance"
      },
      {
        "label": "B",
        "text": "Maintenance → Action → Preparation → Contemplation → Precontemplation"
      },
      {
        "label": "C",
        "text": "Precontemplation → Contemplation → Preparation → Maintenance → Action"
      },
      {
        "label": "D",
        "text": "Precontemplation → Contemplation → Preparation → Action → Maintenance"
      }
    ],
    "correct": [
      3
    ],
    "type": "choice",
    "answer": "D. Precontemplation → Contemplation → Preparation → Action → Maintenance",
    "rationale": "Precontemplation is the first stage of the transtheoretical model. This is the stage when an individual is not even considering making a change.\n\nContemplation is the second stage of the transtheoretical model. This is the stage when an individual is thinking about making a change within the next 6 months.\n\nPreparation is the third stage of the transtheoretical model. Once an individual has made the decision to change, the next stage is preparation. This is the stage when the individual takes steps to get ready to take action.\n\nAction is the fourth stage of the transtheoretical model. This is the stage when an individual has made a change and has been consistent, but for less than 6 months.\n\nMaintenance is the fifth stage of the transtheoretical model. This stage is reached when an individual has remained consistent for more than 6 months.",
    "addedChoices": true,
    "rationaleKind": "Source rationale",
    "rationaleUrl": null
  },
